const wf = $('Zoho Push Webhook').first()?.json || {};
const body = wf.body || wf;
const ctx = $input.first()?.json || {};
return [{ json: Object.assign({}, body, { crmCtx: ctx }) }];

const wf = $('Zoho Push Webhook').first()?.json || {};
const body = wf.body || wf;
const ctx = $input.first()?.json || {};
return [{ json: Object.assign({}, body, { projectsCtx: ctx }) }];

const wf = $('Zoho Push Webhook').first()?.json || {};
const body = wf.body || wf;
const ctx = $input.first()?.json || {};
return [{ json: Object.assign({}, body, { booksCtx: ctx }) }];

const m = $('Merge Books Context').first()?.json || {};
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  campaignId: m.campaignId || null, zoho: { dealId: null, projectId: null, invoiceId: null },
  failures: [], contextSource: (m.crmCtx && m.crmCtx.contextSource) || 'fallback', degraded: false, error: null,
  diagnostics: { requestId: 'push-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-17-zoho-push' }
};
function refuse(code, msg, guidance) { envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance || 'none'; return [{ json: envelope }]; }
if (!m.campaignId) return refuse('empty', 'A campaignId is required to push a campaign to Zoho.', 'none');
const trio = [
  ['Zoho CRM', m.crmCtx, 'connect your Zoho account in Connections'],
  ['Zoho Projects', m.projectsCtx, 'connect Zoho Projects in Connections or ask your admin to enable it'],
  ['Zoho Books', m.booksCtx, 'connect Zoho Books in Connections or ask your admin to enable it']
];
const problems = [];
trio.forEach(function (t) {
  const ctx = t[1] || {};
  if (ctx.enabled === false) problems.push(t[0] + ' is turned off - enable it in Connections.');
  else if (ctx.entitlement === false) problems.push('Your account does not have access to ' + t[0] + ' - ask your admin to unlock it.');
  else if (!ctx.accessToken) problems.push(t[0] + ' is not connected yet - ' + t[2] + '.');
});
if (problems.length) return refuse('missing_connector', problems.join(' '), 'connect');
const supabaseUrl = String(m.supabaseUrl || 'https://ejawdvxnddgkcgkasove.supabase.co').trim();
const out = Object.assign({}, envelope, { ok: true, status: 'pending', organizationId: m.organizationId || null, userId: m.userId || null, supabaseUrl: supabaseUrl, contextSource: (m.crmCtx && m.crmCtx.contextSource) || 'fallback', degraded: (m.crmCtx && m.crmCtx.degraded === true) });
if (supabaseUrl) {
  out.status = 'pending_fetch';
  out.campaignFetchUrl = supabaseUrl.replace(/\/+$/, '') + '/rest/v1/campaigns?id=eq.' + encodeURIComponent(m.campaignId) + '&select=*';
  return [{ json: out }];
}
out.status = 'pending_gate';
out.campaign = (m.campaign && typeof m.campaign === 'object') ? m.campaign : null;
out.approvalNotes = m.approvalNotes || null;
return [{ json: out }];

const row = $input.first()?.json || {};
const gateA = $('Gate Connectors & Prepare Campaign Fetch').first()?.json || {};
return [{ json: Object.assign({}, gateA, { fetchedCampaign: [row], status: 'pending_gate' }) }];

const m = $('Merge Books Context').first()?.json || {};
const gateA = $input.first()?.json || {};
const fetched = Array.isArray(gateA.fetchedCampaign) ? gateA.fetchedCampaign[0] : null;
const campaign = fetched || gateA.campaign || (m.campaign && typeof m.campaign === 'object' ? m.campaign : null);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  campaignId: gateA.campaignId || null, zoho: { dealId: null, projectId: null, invoiceId: null },
  failures: [], contextSource: gateA.contextSource || 'fallback', degraded: gateA.degraded === true, error: null,
  diagnostics: gateA.diagnostics || { requestId: 'push-' + Date.now(), workflow: 'prism-17-zoho-push' }
};
function refuse(code, msg, guidance) { envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance || 'none'; return [{ json: envelope }]; }
if (!campaign || !campaign.id) return refuse('campaign_not_found', 'Campaign ' + (gateA.campaignId || '') + ' was not found - refresh the Campaigns view and try again.', 'none');
const statusOk = String(campaign.status || '').toLowerCase() === 'approved';
if (!statusOk && gateA.degraded !== true) return refuse('not_approved', 'This campaign is not approved yet - only campaigns with status Approved can be pushed to Zoho.', 'approve');
if (!statusOk && gateA.degraded === true && gateA.approvalNotes === undefined) return refuse('not_approved', 'This campaign is not approved yet - approve it in the Campaigns view first.', 'approve');
const existing = { deal_id: campaign.deal_id || null, project_id: campaign.project_id || null, invoice_id: campaign.invoice_id || null };
if (existing.deal_id && existing.project_id && existing.invoice_id && !gateA.force) {
  envelope.zoho = { dealId: existing.deal_id, projectId: existing.project_id, invoiceId: existing.invoice_id };
  envelope.existing = existing;
  return refuse('already_pushed', 'This campaign was already pushed to Zoho - nothing left to create.', 'none');
}
let envDc = 'in';
try { envDc = String($env.PRISM_ZOHO_DC || 'in'); } catch (e) {}
const orgCfgAll = Object.assign({}, (m.crmCtx && m.crmCtx.orgConfig) || {}, (m.projectsCtx && m.projectsCtx.orgConfig) || {}, (m.booksCtx && m.booksCtx.orgConfig) || {});
const dc = String(orgCfgAll.dataCenter || envDc).replace(/^zoho\./, '');
const plan = {
  ok: true, status: 'pending_write', campaignId: gateA.campaignId, campaignName: campaign.name || 'Untitled campaign',
  organizationId: gateA.organizationId || null, userId: gateA.userId || null, supabaseUrl: gateA.supabaseUrl || '',
  approvalNotes: gateA.approvalNotes || null, existing: existing, failures: [], contextSource: gateA.contextSource || 'fallback', degraded: gateA.degraded === true,
  diagnostics: envelope.diagnostics, campaign: { name: campaign.name || '', budget: campaign.budget != null ? Number(campaign.budget) : 0, brief: campaign.brief || '', client: campaign.client || '', stage: campaign.stage || 'Qualification' }
};
plan.dealUrl = 'https://www.zohoapis.' + dc + '/crm/v2/Deals';
plan.dealBody = JSON.stringify({ data: [{ Deal_Name: plan.campaignName, Amount: plan.campaign.budget, Stage: plan.campaign.stage, Account_Name: plan.campaign.client || undefined, Description: (plan.campaign.brief || '') + (gateA.approvalNotes ? ('\n\nApproval notes: ' + gateA.approvalNotes) : '') }].map(function (d) { return JSON.parse(JSON.stringify(d)); }) });
const portalId = String(orgCfgAll.portalId || '').trim();
if (portalId) {
  plan.projectUrl = 'https://projectsapi.' + dc + '/restapi/portal/' + portalId + '/projects/';
  plan.projectName = plan.campaignName;
  plan.projectDesc = (plan.campaign.brief || '') + (gateA.approvalNotes ? ('\nApproval notes: ' + gateA.approvalNotes) : '');
} else {
  plan.failures.push({ system: 'zoho_projects', reasonCode: 'portal_not_configured', message: 'Zoho Projects portal ID is missing from org config - project was not created.' });
}
const booksOrg = String(orgCfgAll.booksOrgId || '').trim();
const customerId = campaign.customer_id || m.customerId || null;
if (booksOrg) {
  if (customerId) {
    plan.invoiceUrl = 'https://www.zohoapis.' + dc + '/books/v3/invoices?organization_id=' + encodeURIComponent(booksOrg);
    plan.invoiceBody = JSON.stringify({ customer_id: customerId, reference_number: 'Campaign: ' + plan.campaignName, line_items: [{ name: plan.campaignName, description: plan.campaign.brief || '', quantity: 1, rate: plan.campaign.budget }] });
  } else {
    plan.failures.push({ system: 'zoho_books', reasonCode: 'books_customer_missing', message: 'No Zoho Books customer is linked to this campaign - set customer_id on the campaign before pushing.' });
  }
} else {
  plan.failures.push({ system: 'zoho_books', reasonCode: 'org_not_configured', message: 'Zoho Books organization ID is missing from org config - invoice was not created.' });
}
if (existing.deal_id) plan.skipDeal = true;
if (existing.project_id) plan.skipProject = true;
if (existing.invoice_id) plan.skipInvoice = true;
return [{ json: plan }];

const plan = $('Gate Approval & Build Write Plan').first()?.json || {};
const dealRes = $('Create Zoho CRM Deal').first()?.json || {};
const projRes = $('Create Zoho Project').first()?.json || {};
const invRes = $('Create Zoho Books Invoice').first()?.json || {};
const envelope = {
  ok: false, status: 'partial', reasonCode: 'none', guidance: 'none', userMessage: null,
  campaignId: plan.campaignId || null, zoho: { dealId: plan.existing && plan.existing.deal_id ? plan.existing.deal_id : null, projectId: plan.existing && plan.existing.project_id ? plan.existing.project_id : null, invoiceId: plan.existing && plan.existing.invoice_id ? plan.existing.invoice_id : null },
  failures: Array.isArray(plan.failures) ? plan.failures.slice() : [], contextSource: plan.contextSource || 'fallback', degraded: plan.degraded === true, error: null,
  diagnostics: plan.diagnostics || { requestId: 'push-' + Date.now(), workflow: 'prism-17-zoho-push' }
};
if (!plan.skipDeal) {
  const d = (dealRes.data && dealRes.data[0]) || {};
  if (d.code === 'SUCCESS' && d.details && d.details.id) envelope.zoho.dealId = String(d.details.id);
  else envelope.failures.push({ system: 'zoho_crm', reasonCode: 'deal_create_failed', message: 'Zoho CRM deal creation failed (' + String(d.code || dealRes.statusCode || 'unknown') + '): ' + String((d.message || dealRes.message || 'unknown error')) });
}
if (!plan.skipProject && plan.projectUrl) {
  const p = projRes.projects && projRes.projects[0] ? projRes.projects[0] : (projRes.retStat === 'ok' ? projRes.project || null : null);
  const pid = p && (p.id || p.project_id) ? String(p.id || p.project_id) : null;
  if (pid) envelope.zoho.projectId = pid;
  else envelope.failures.push({ system: 'zoho_projects', reasonCode: 'project_create_failed', message: 'Zoho Projects creation failed (' + String(projRes.retStat || projRes.statusCode || 'unknown') + '): ' + String(projRes.error && projRes.error.message ? projRes.error.message : (projRes.message || 'unknown error')) });
}
if (!plan.skipInvoice && plan.invoiceUrl) {
  const inv = invRes.invoice || null;
  if (inv && inv.invoice_id) envelope.zoho.invoiceId = String(inv.invoice_id);
  else envelope.failures.push({ system: 'zoho_books', reasonCode: 'invoice_create_failed', message: 'Zoho Books invoice creation failed (' + String(invRes.code || invRes.statusCode || 'unknown') + '): ' + String((invRes.message || 'unknown error')) });
}
const created = [envelope.zoho.dealId && !(plan.existing && plan.existing.deal_id), envelope.zoho.projectId && !(plan.existing && plan.existing.project_id), envelope.zoho.invoiceId && !(plan.existing && plan.existing.invoice_id)].filter(Boolean).length;
const hadConfigFailure = envelope.failures.length > 0;
if (!hadConfigFailure) { envelope.ok = true; envelope.status = 'success'; envelope.userMessage = null; }
else if (created > 0 || envelope.zoho.dealId || envelope.zoho.projectId || envelope.zoho.invoiceId) { envelope.ok = true; envelope.status = 'partial'; envelope.reasonCode = 'partial_push'; envelope.guidance = 'retry'; envelope.userMessage = 'Pushed partially to Zoho - ' + envelope.failures.length + ' item(s) failed and can be retried safely (already-created items are skipped).'; }
else { envelope.ok = false; envelope.status = 'failed'; envelope.reasonCode = 'push_failed'; envelope.guidance = 'retry'; envelope.userMessage = 'The Zoho push failed - nothing was written. Review the failure reasons and try again.'; }
envelope.success = envelope.ok && !hadConfigFailure;
envelope.updates = {};
if (envelope.zoho.dealId && !(plan.existing && plan.existing.deal_id)) envelope.updates.deal_id = envelope.zoho.dealId;
if (envelope.zoho.projectId && !(plan.existing && plan.existing.project_id)) envelope.updates.project_id = envelope.zoho.projectId;
if (envelope.zoho.invoiceId && !(plan.existing && plan.existing.invoice_id)) envelope.updates.invoice_id = envelope.zoho.invoiceId;
const su = String(plan.supabaseUrl || '').trim();
envelope.campaignPatchUrl = su && Object.keys(envelope.updates).length ? su.replace(/\/+$/, '') + '/rest/v1/campaigns?id=eq.' + encodeURIComponent(plan.campaignId) : '';
envelope.auditUrl = su ? su.replace(/\/+$/, '') + '/rest/v1/agent_audit_logs' : '';
envelope.auditBody = JSON.stringify({ organization_id: plan.organizationId || null, user_id: plan.userId || null, campaign_id: plan.campaignId || null, action: 'campaign.zoho_push', status: envelope.status, deal_id: envelope.zoho.dealId, project_id: envelope.zoho.projectId, invoice_id: envelope.zoho.invoiceId, failure_count: envelope.failures.length, request_id: envelope.diagnostics.requestId });
return [{ json: envelope }];

let env = null;
const ins = $input.all();
for (let i = 0; i < ins.length; i++) { const j = ins[i] && ins[i].json ? ins[i].json : {}; if (j && (j.diagnostics || j.ok !== undefined || j.reasonCode)) { env = j; break; } }
if (!env) { try { env = $('Assemble Push Result').first()?.json || {}; } catch (e) { env = { ok: false, status: 'error', reasonCode: 'push_failed', guidance: 'retry', userMessage: 'No push result was produced - check the execution log.', zoho: { dealId: null, projectId: null, invoiceId: null }, failures: [], diagnostics: { requestId: 'push-' + Date.now(), workflow: 'prism-17-zoho-push' } }; } }
return [{ json: env }];
